    WheelSet() {
    }

    String describe() {
        return "wheels";
    }
}

// Provided -- do not edit.
class RoadCar {

    private final MotorUnit motor;
    private final WheelSet wheels;

    RoadCar(MotorUnit motor, WheelSet wheels) {
        this.motor = motor;
        this.wheels = wheels;
    }

    String describe() {
        return "car(" + motor.describe() + "," + wheels.describe() + ")";
    }
}

// Provided -- do not edit.
class CarDepot {

    private final RoadCar car;

    CarDepot(RoadCar car) {
        this.car = car;
    }

    String describe() {
        return "depot[" + car.describe() + "]";
    }
}

