public class TinyInjectorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String describe(Class<?> type) {
        try {
            Object built = TinyInjector.build(type);
            if (built == null) {
                return "null";
            }
            java.lang.reflect.Method m = type.getDeclaredMethod("describe");
            m.setAccessible(true);
            return String.valueOf(m.invoke(built));
        } catch (Throwable t) {
            return "threw " + t.getClass().getSimpleName();
        }
    }

    static String errorOf(Class<?> type) {
        try {
            TinyInjector.build(type);
            return "no exception";
        } catch (Throwable t) {
            return t.getClass().getSimpleName() + ": " + t.getMessage();
        }
    }

    static boolean freshEachTime() {
        try {
            return TinyInjector.build(MotorUnit.class) != TinyInjector.build(MotorUnit.class);
        } catch (Throwable t) {
            return false;
        }
    }

    public static void main(String[] args) {
        check("build a type with a no-argument constructor", "motor", describe(MotorUnit.class));
        check("build another leaf type", "wheels", describe(WheelSet.class));
        check("build a type whose constructor needs two others", "car(motor,wheels)",
                describe(RoadCar.class));
        check("build two levels deep", "depot[car(motor,wheels)]", describe(CarDepot.class));
        check("every build returns a fresh instance", true, freshEachTime());
        check("a type needing a String cannot be built",
                "IllegalArgumentException: cannot build java.lang.String", errorOf(HandTool.class));
        check("String itself is rejected the same way",
                "IllegalArgumentException: cannot build java.lang.String", errorOf(String.class));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

